create extension if not exists pg_trgm;
create table public.admin_users(id uuid primary key references auth.users(id), active boolean not null default true);
create function public.is_admin() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.admin_users where id=(select auth.uid()) and active)$$;
create function public.assert_admin() returns void language plpgsql security definer set search_path='' as $$begin if not public.is_admin() then raise exception 'ADMIN_REQUIRED' using errcode='42501';end if;end$$;
create table public.site_profile(id boolean primary key default true check(id),data jsonb not null,version integer not null default 1,updated_at timestamptz not null default now());
create table public.anniversaries(id uuid primary key default gen_random_uuid(),key text unique check(key in ('birthday','debut')),name text not null,type text not null check(type in ('annual','debut','once','schedule')),date_value date,month smallint,day smallint,birth_year smallint,time_value time,note text not null default '',visible boolean not null default true,display_order integer not null default 0,version integer not null default 1,check((type='annual' and date_value is null and month between 1 and 12 and day between 1 and extract(day from (make_date(2000,month,1)+interval '1 month - 1 day'))) or (type<>'annual' and date_value is not null and month is null and day is null)));
create table public.site_assets(id uuid primary key default gen_random_uuid(),path text not null unique,mime text not null,bytes integer not null check(bytes between 1 and 3145728),width integer not null,height integer not null,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.signatures(id uuid primary key default gen_random_uuid(),name text not null check(length(name) between 1 and 100),balloon_count integer not null check(balloon_count>0),description text not null default '',category text not null default '',image text not null,display_order integer not null default 0,is_visible boolean not null default false,version integer not null default 1);
create index signatures_public on public.signatures(is_visible,balloon_count,display_order,id);
create table public.songs(id uuid primary key default gen_random_uuid(),title text not null check(length(title) between 1 and 200),artist_name text not null check(length(artist_name) between 1 and 200),album_title text not null default '',version_label text not null default '',release_date_text text not null default '',difficulty_steps smallint check(difficulty_steps between 1 and 10),difficulty_note text not null default '',cover_url text,cover_source_url text,cover_asset_id uuid references public.site_assets(id),cover_alt text not null default '',is_visible boolean not null default false,version integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),search_text text not null default '',title_sort text not null default '',artist_sort text not null default '',check(cover_asset_id is null or cover_source_url is null));
create index songs_search on public.songs using gin(search_text gin_trgm_ops);
create index songs_title on public.songs(is_visible,title_sort collate "C",artist_sort collate "C",id);
create index songs_difficulty on public.songs(is_visible,difficulty_steps,title_sort collate "C",id);
create index songs_newest on public.songs(is_visible,created_at desc,id);
create table public.song_categories(id uuid primary key default gen_random_uuid(),name text not null check(length(name) between 1 and 50),normalized_name text not null unique,slug text not null unique,active boolean not null default true,display_order integer not null default 0,version integer not null default 1);
create table public.song_category_links(song_id uuid references public.songs(id) on delete cascade,category_id uuid references public.song_categories(id),primary key(song_id,category_id));
create index song_category_reverse on public.song_category_links(category_id,song_id);
create table public.song_youtube_links(id uuid primary key default gen_random_uuid(),song_id uuid not null references public.songs(id) on delete cascade,kind text not null check(kind in ('original','karaoke')),video_id text not null check(video_id~'^[a-zA-Z0-9_-]{11}$'),url text not null,source text not null default 'manual' check(source='manual'),unique(song_id,kind),check(url='https://www.youtube.com/watch?v='||video_id));
create table public.song_admin_metadata(song_id uuid primary key references public.songs(id) on delete cascade,memo text not null default '',cover_usage_basis text not null default '',metadata jsonb);
create table public.site_settings(id boolean primary key default true check(id),data jsonb not null default '{}',version integer not null default 1);
insert into public.site_settings(id) values(true);
create table public.obligation_types(id uuid primary key default gen_random_uuid(),name text not null unique,unit text not null,integer_only boolean not null default true,active boolean not null default true);
insert into public.obligation_types(name,unit,integer_only) values('방셀','장',true),('노래','곡',true),('시간 미션','분',false);
create table public.viewer_accounts(id uuid primary key default gen_random_uuid(),soop_id text not null unique check(length(soop_id) between 1 and 100),nickname text not null check(length(nickname) between 1 and 100),source_user_key text);
create table public.obligation_accounts(id uuid primary key default gen_random_uuid(),viewer_id uuid not null references public.viewer_accounts(id),type_id uuid not null references public.obligation_types(id),version integer not null default 0,unique(viewer_id,type_id));
create table public.obligation_ledger(id uuid primary key default gen_random_uuid(),account_id uuid not null references public.obligation_accounts(id),delta numeric(14,3) not null check(delta<>0),kind text not null check(kind in ('acquire','adjust','fulfill','invalidate','reverse','request_complete','request_reopen','roulette')),reason text not null,source_event_id uuid,source_request_id uuid,reverse_of uuid unique references public.obligation_ledger(id),created_by uuid references auth.users(id),created_at timestamptz not null default now());
create index ledger_account on public.obligation_ledger(account_id,created_at desc,id);
create unique index ledger_event on public.obligation_ledger(source_event_id) where source_event_id is not null;
create table public.photo_requests(id uuid primary key default gen_random_uuid(),receipt text not null unique default ('R-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,16))),nickname text not null check(length(nickname) between 1 and 100),soop_id text not null check(length(soop_id) between 1 and 100),message text not null default '' check(length(message)<=1000),status text not null default 'received' check(status in ('received','reviewing','in_progress','completed','on_hold','cancelled')),memo text not null default '',account_id uuid references public.obligation_accounts(id),quantity numeric(14,3) not null default 1 check(quantity>0),completion_entry uuid references public.obligation_ledger(id),version integer not null default 1,created_at timestamptz not null default now());
create index requests_status_date on public.photo_requests(status,created_at desc,id);
create table public.roulette_catalog(id boolean primary key default true check(id),data jsonb not null,version text not null,last_success_at timestamptz not null default now());
create table public.roulette_mappings(key text primary key,type_id uuid references public.obligation_types(id),quantity numeric(14,3),ignore boolean not null default false,check((ignore and type_id is null) or (not ignore and type_id is not null and quantity>0)));
create table public.roulette_events(id uuid primary key default gen_random_uuid(),receipt_id uuid not null unique,source_key text unique,payload jsonb not null,payload_hash text not null,status text not null check(status in ('applied','review_required','ignored')),reason text not null default '',received_at timestamptz not null default now());
create index events_review on public.roulette_events(status,received_at desc);
create table public.collector_state(id boolean primary key default true check(id),data jsonb not null default '{}',observed_at timestamptz not null default now());
create table public.admin_audit_logs(id bigint generated always as identity primary key,actor uuid,action text not null,target text,detail jsonb not null default '{}',created_at timestamptz not null default now());
create table public.operation_keys(scope text not null,key uuid not null,payload_hash text not null,result jsonb,created_at timestamptz not null default now(),primary key(scope,key));
create table public.request_rate_limits(key text primary key,starts_at timestamptz not null,count integer not null,expires_at timestamptz not null);
create table public.provider_request_limits(key text primary key,next_at timestamptz not null);
create table public.songbook_lookup_cache(id uuid primary key default gen_random_uuid(),provider text not null,request_key text not null,data jsonb not null,expires_at timestamptz not null,unique(provider,request_key));
create table public.broadcast_cache(id boolean primary key default true check(id),data jsonb not null default '{}',last_attempt_at timestamptz,last_success_at timestamptz,lease_until timestamptz);
insert into public.broadcast_cache(id) values(true);

create function public.audit(p_action text,p_target text,p_detail jsonb default '{}') returns void language sql security definer set search_path='' as $$insert into public.admin_audit_logs(actor,action,target,detail) values(auth.uid(),p_action,p_target,p_detail)$$;
create function public.operation_begin(p_scope text,p_key uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare old public.operation_keys; s text:=coalesce(auth.uid()::text,'service')||':'||p_scope;h text:=encode(sha256(convert_to(p_payload::text,'UTF8')),'hex');begin perform pg_advisory_xact_lock(hashtextextended(s||p_key::text,0));select * into old from public.operation_keys where scope=s and key=p_key;if found then if old.payload_hash<>h then raise exception 'IDEMPOTENCY_CONFLICT' using errcode='23505';end if;return old.result;end if;insert into public.operation_keys(scope,key,payload_hash) values(s,p_key,h);return null;end$$;
create function public.operation_finish(p_scope text,p_key uuid,p_result jsonb) returns jsonb language plpgsql security definer set search_path='' as $$begin update public.operation_keys set result=p_result where scope=coalesce(auth.uid()::text,'service')||':'||p_scope and key=p_key;return p_result;end$$;
create function public.consume_limit(p_key text,p_limit integer,p_seconds integer) returns boolean language plpgsql security definer set search_path='' as $$declare n integer;begin insert into public.request_rate_limits(key,starts_at,count,expires_at) values(p_key,now(),1,now()+make_interval(secs=>p_seconds)) on conflict(key) do update set count=case when request_rate_limits.expires_at<=now() then 1 else request_rate_limits.count+1 end,starts_at=case when request_rate_limits.expires_at<=now() then now() else request_rate_limits.starts_at end,expires_at=case when request_rate_limits.expires_at<=now() then now()+make_interval(secs=>p_seconds) else request_rate_limits.expires_at end returning count into n;delete from public.request_rate_limits where key in(select key from public.request_rate_limits where expires_at<now()-interval '1 day' limit 100);return n<=p_limit;end$$;
create function public.claim_provider(p_key text,p_milliseconds integer) returns boolean language plpgsql security definer set search_path='' as $$declare ok boolean;begin insert into public.provider_request_limits(key,next_at) values(p_key,now()+make_interval(secs=>p_milliseconds/1000.0)) on conflict(key) do update set next_at=excluded.next_at where provider_request_limits.next_at<=now() returning true into ok;return coalesce(ok,false);end$$;

alter table public.admin_users enable row level security;
create policy admin_self on public.admin_users for select to authenticated using(id=(select auth.uid()));
do $$declare t text;begin foreach t in array array['site_profile','anniversaries','site_assets','signatures','songs','song_categories','song_category_links','song_youtube_links','song_admin_metadata','site_settings','obligation_types','viewer_accounts','obligation_accounts','obligation_ledger','photo_requests','roulette_catalog','roulette_mappings','roulette_events','collector_state','admin_audit_logs','operation_keys','request_rate_limits','provider_request_limits','songbook_lookup_cache','broadcast_cache'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy admin_read on public.%I for select to authenticated using ((select public.is_admin()))',t);end loop;end$$;
create policy visible_anniversary on public.anniversaries for select to anon,authenticated using(visible);
create policy visible_signature on public.signatures for select to anon,authenticated using(is_visible);
create policy visible_song on public.songs for select to anon,authenticated using(is_visible);
create policy visible_category on public.song_categories for select to anon,authenticated using(active);
create policy visible_link on public.song_category_links for select to anon,authenticated using(exists(select 1 from public.songs where id=song_id and is_visible));
create policy visible_video on public.song_youtube_links for select to anon,authenticated using(exists(select 1 from public.songs where id=song_id and is_visible));
grant select on all tables in schema public to authenticated;
grant select on public.anniversaries,public.signatures,public.songs,public.song_categories,public.song_category_links,public.song_youtube_links to anon;
revoke all on all functions in schema public from public,anon,authenticated;
grant execute on function public.is_admin() to anon,authenticated,service_role;
grant execute on function public.consume_limit(text,integer,integer),public.claim_provider(text,integer) to service_role;
grant all on all tables in schema public to service_role;
grant usage,select on all sequences in schema public to service_role;
